// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(uint256 deposit) public {
        deposit = bound(deposit, 1, type(uint256).max);

        address payer = address(0xBEEF);
        vm.deal(payer, deposit);

        vm.prank(payer);
        (bool sent, ) = address(c).call{value: deposit}("");
        require(sent);

        address recipient = address(0xF00D);

        c.withdrawAll(recipient);

        assertTrue(address(c).balance == 0);
    }
}
